    fn find_free_tcp_port() -> u16 {
        std::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST, 0))
            .expect("failed to reserve TCP port")
            .local_addr()
            .unwrap()
            .port()
    }

