#[repr(C)]
#[derive(Clone, Copy, Debug, Eq, FromBytes, Immutable, IntoBytes, PartialEq)]
struct ThreadBasicInformation {
    exit_status: i32,
    _padding0: u32,
    teb_base_address: usize,
