}

Serializer! {
    /// Unique identifier for a file
    #[derive(Clone, Debug, Copy)]
    pub(super) struct Qid {
        pub(super) typ: QidType,
        pub(super) version: u32,
        pub(super) path: u64,
    }
}

Serializer! {
    /// File system statistics
    #[derive(Clone, Debug, Copy)]
    struct Statfs {
        typ: u32,
        bsize: u32,
        blocks: u64,
        bfree: u64,
        bavail: u64,
        files: u64,
        ffree: u64,
        fsid: u64,
        namelen: u32,
    }
}

Serializer! {
    /// Time structure
    #[derive(Clone, Debug, Copy, Default)]
    pub(super) struct Time {
        sec: u64,
        nsec: u64,
    }
}

Serializer! {
    /// File attributes
    #[derive(Clone, Debug, Copy)]
    pub(super) struct Stat {
        pub(super) mode: u32,
        pub(super) uid: u32,
        pub(super) gid: u32,
        pub(super) nlink: u64,
        pub(super) rdev: u64,
        pub(super) size: u64,
