Serializer! {
    /// Set file attributes
    #[derive(Clone, Debug, Copy, Default)]
    pub(super) struct SetAttr {
        pub(super) mode: u32,
        pub(super) uid: u32,
        pub(super) gid: u32,
        pub(super) size: u64,
        pub(super) atime: Time,
        pub(super) mtime: Time,
    }
}

Serializer! {
    /// Directory entry
    #[derive(Clone, Debug)]
    pub(super) struct DirEntry<'a> {
        pub(super) qid: Qid,
        pub(super) offset: u64,
        pub(super) typ: u8,
        pub(super) name: FcallStr<'a>,
    }
}

impl DirEntry<'_> {
    /// Create an owned copy of this directory entry.
    pub(super) fn into_owned(self) -> DirEntry<'static> {
        DirEntry {
            qid: self.qid,
            offset: self.offset,
            typ: self.typ,
            name: Cow::Owned(self.name.into_owned()),
        }
    }

    /// Calculate the size of this entry when encoded
    fn size(&self) -> u64 {
        (13 + 8 + 1 + 2 + self.name.len()) as u64
    }
}

Serializer! {
    /// File lock request
    #[derive(Clone, Debug)]
    pub(super) struct Flock<'a> {
        typ: LockType,
        flags: LockFlag,
        start: u64,
        length: u64,
        proc_id: u32,
        client_id: FcallStr<'a>,
    }
