        client_id: FcallStr<'a>,
    }
}

// ============================================================================
// Response/Request structures
// ============================================================================

Serializer! {
    /// Error response
    #[derive(Clone, Debug)]
    pub(super) struct Rlerror {
        pub(super) ecode: u32,
    }
}

impl core::fmt::Display for Rlerror {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(f, "Remote error: {}", self.ecode)
    }
}

Serializer! {
    /// Attach request
    #[derive(Clone, Debug)]
    pub(super) struct Tattach<'a> {
        pub(super) fid: u32,
        pub(super) afid: u32,
        pub(super) uname: FcallStr<'a>,
        pub(super) aname: FcallStr<'a>,
        pub(super) n_uname: u32,
    }
}

Serializer! {
    /// Attach response
    #[derive(Clone, Debug)]
    pub(super) struct Rattach {
        pub(super) qid: Qid,
    }
}

Serializer! {
    /// Statfs request
    #[derive(Clone, Debug)]
    pub(super) struct Tstatfs {
        fid: u32,
    }
}

Serializer! {
    /// Statfs response
    #[derive(Clone, Debug)]
    pub(super) struct Rstatfs {
        statfs: Statfs,
    }
}

Serializer! {
    /// Open request
