#[test]
fn tcp_pending_errors_preserve_order_and_source() {
    let mut errors = TcpPendingErrors::default();
    errors.append(TcpPendingError::Socket(SocketError::ConnectionReset));
    errors.append(TcpPendingError::GuestReset);
    errors.append(TcpPendingError::GuestReset);

