/// +-------------------------------+
/// | CommandLine                   |
/// +-------------------------------+
/// | WindowTitle                   |
/// +-------------------------------+
/// | DesktopInfo                   |
/// +-------------------------------+
/// | ShellInfo                     |
/// +-------------------------------+
/// | RuntimeData                   |
/// +-------------------------------+
/// | RedirectionDllName            |
/// +-------------------------------+
/// ```
