            let host_status = unsafe { NtSetEvent(host_handle, &raw mut host_previous) };
            let shim_status = task.sys_nt_set_event(shim_handle, Some(mut_ptr(&mut shim_previous)));
            assert_status_eq(shim_status, host_status);
