        const MEM_COMMIT = 0x1000;
        const MEM_RESERVE = 0x2000;
        const MEM_RESET = 0x80000;
        const MEM_TOP_DOWN = 0x100000;
        const MEM_WRITE_WATCH = 0x200000;
        const MEM_PHYSICAL = 0x400000;
