        // SAFETY: This is the host's documented size-query shape: a writable size pointer and a
        // null data buffer.
        let status = unsafe {
            NtGetMUIRegistryInfo(0, core::ptr::addr_of_mut!(host_size), core::ptr::null_mut())
        };
        assert_eq!(host_status(status), NtStatus::SUCCESS);
        assert_eq!(
