                .unwrap()
                .len()
        );

        let mut host_data = vec![0; host_size as usize];
        // SAFETY: `host_data` is a writable buffer of the size returned by the host query.
        let status = unsafe {
            NtGetMUIRegistryInfo(
                0,
                core::ptr::addr_of_mut!(host_size),
                host_data.as_mut_ptr(),
