            path,
            |node| node.port_object(),
            ObjectNode::new_port,
            NtStatus::OBJECT_TYPE_MISMATCH,
            |()| NtStatus::OBJECT_NAME_EXISTS,
            |_| NtStatus::SUCCESS,
        )
